/**
 * AUTO-GENERATED automation — created by the spell-automation-generate skill
 * from spell-automation-proposals.md (2026-07-06).
 * Proposal feasibility: needs-new-event (damage-applied-to-actor event carrying
 * type and total on the warded target does not exist today).
 * Degraded parts (manual): the automatic 1d4 reduction of the first chosen-type
 * damage each turn, and its per-turn reset — both need a damage-taken event that
 * the framework does not expose; the tracking effect's description carries the
 * manual rule instead. Cross-actor writes to an unowned ward target go through
 * the GM relay (applyEffectToActor) and are skipped only when no GM is online.
 *
 * Review before trusting. Regenerating this spell OVERWRITES this file.
 * To adopt as manually maintained: remove this banner and the `autogenerated`
 * flag in the definition below — regeneration will then refuse to touch it.
 */

import {MODULE_ID} from '../../framework/constants.js';
import {applyEffectToActor, deleteDocument} from '../../framework/utils.js';

/**
 * Resistance (Cantrip, PHB'24) — ward a willing creature you touch against one
 * damage type. In these rules, the first instance of the chosen type of damage
 * the warded creature takes each turn is reduced by 1d4 (concentration).
 *
 * What is automated:
 *   - A cast-time dialog to pick which damage type to protect against.
 *   - A concentration-linked tracking ActiveEffect placed on the warded creature
 *     recording the chosen type, so everyone can see what is warded and it ends
 *     with concentration. Owned targets are written directly; unowned targets go
 *     through the GM relay (applyEffectToActor), where the GM's client also binds
 *     the effect to concentration via the flags[MODULE_ID].concentrationUuid link.
 *
 * What is NOT automated:
 *   - The actual 1d4 reduction of incoming damage and its once-per-turn reset.
 *     No "damage about to be applied to an actor" event exists in the framework,
 *     so the automation cannot see the warded creature take damage. The tracking
 *     effect's description carries the rule; the GM/player subtracts 1d4 by hand.
 *   - Warding an unowned target while no GM is online — there is no client that
 *     may perform the write, so it is skipped (logged to console).
 *   - The PHB'14 variant (add 1d4 to one saving throw) is left as rules text only.
 */

const DAMAGE_TYPE_CHOICES = {
    acid: 'Acid',
    bludgeoning: 'Bludgeoning',
    cold: 'Cold',
    fire: 'Fire',
    force: 'Force',
    lightning: 'Lightning',
    necrotic: 'Necrotic',
    piercing: 'Piercing',
    poison: 'Poison',
    psychic: 'Psychic',
    radiant: 'Radiant',
    slashing: 'Slashing',
    thunder: 'Thunder'
};

/**
 * Resolve the warded creature: the (single) targeted token's actor, falling back
 * to the caster (Resistance can ward yourself). Reading a target actor is always
 * safe — only writes need ownership.
 */
function resolveWardTarget(context) {
    const targets = [...(game.user.targets ?? [])];
    const targetActor = targets[0]?.actor ?? null;
    return targetActor ?? context.actor ?? null;
}

async function cast(context) {
    const {actor, item} = context;
    if (!actor) return;

    const damageType = await foundry.applications.api.DialogV2.wait({
        window: {title: item.name},
        content: '<p>Which damage type should the ward protect against?</p>',
        buttons: Object.entries(DAMAGE_TYPE_CHOICES).map(([action, label], index) => ({
            action,
            label,
            default: index === 0
        })),
        rejectClose: false
    }).catch(() => null);
    if (!damageType) return;

    const typeLabel = DAMAGE_TYPE_CHOICES[damageType] ?? damageType;
    const target = resolveWardTarget(context);

    // Concentration effect the ward is bound to, so it ends with concentration.
    const concentration = context.results?.effects
        ?.find(effect => effect.statuses?.has?.(CONFIG.specialStatusEffects.CONCENTRATING)) ?? null;

    // Place the tracking effect on the ward target: written directly when owned,
    // relayed through the active GM's client otherwise. Only skip (never block the
    // cast) when neither client may perform the write.
    if (!target) {
        console.warn(`${MODULE_ID} | resistance: no ward target resolved`);
        return;
    }
    const result = await applyWardEffect(target, item, damageType, typeLabel, concentration);
    if (result === false) {
        console.warn(`${MODULE_ID} | resistance: cannot write the tracking effect to `
            + `"${target.name}" — target not owned and no GM online`);
    }
}

/**
 * Create the concentration-linked tracking effect on the warded creature. It carries
 * the chosen type and a description reminder, and is deleted when concentration ends
 * (dnd5e cascades dependent effects off the concentration effect via `dependent`).
 * The write goes through applyEffectToActor, which also performs the addDependent
 * link — on the relayed path the created effect only ever exists on the GM's client,
 * so the concentration uuid travels in flags[MODULE_ID].concentrationUuid.
 * @returns {Promise<'applied'|'relayed'|false>}  How the write was delivered.
 */
async function applyWardEffect(target, item, damageType, typeLabel, concentration) {
    // Replace any previous ward regardless of its type label — the name-based
    // dedupe inside applyEffectToActor only catches same-type re-casts.
    const existing = target.effects.find(effect =>
        effect.getFlag(MODULE_ID, 'resistance'));
    if (existing) await deleteDocument(existing);

    const effectData = {
        name: `${item.name} (${typeLabel})`,
        img: item.img,
        origin: item.uuid,
        description: `<p>Warded against <strong>${typeLabel}</strong> damage. The first instance of `
            + `${typeLabel} damage taken each turn is reduced by 1d4 (roll and subtract manually).</p>`,
        statuses: [],
        flags: {
            [MODULE_ID]: {
                resistance: {damageType},
                // Framework-level link: applyEffectToActor (or its GM relay) binds
                // the created effect to this concentration effect via addDependent.
                concentrationUuid: concentration?.uuid ?? null,
                // The effect shares the spell's name; keep name-matching off it.
                disabledAutomations: ['resistance']
            }
        }
    };

    return applyEffectToActor(target, effectData);
}

export const resistance = {
    id: 'resistance',
    name: 'Resistance',
    description: 'On cast, prompts for the damage type to ward against and places a concentration-linked tracking effect on the warded creature (written directly when owned, relayed through the GM\'s client otherwise); its description carries the rule. The per-turn 1d4 reduction of the first chosen-type damage is NOT auto-applied — no damage-taken event exists, so roll and subtract 1d4 by hand off the marker. Warding an unowned target with no GM online is skipped. The PHB\'14 variant (add 1d4 to a save) is rules text only.',
    version: '1.2.0',
    autogenerated: true,
    match: {
        itemNames: ['Resistance']
    },
    events: [
        // Item-lifecycle: without the scope, the resistance tracking effect on the
        // warded creature routed every spell IT cast back here via effect scope,
        // opening the damage-type picker on unrelated casts.
        {
            event: 'spellCastComplete',
            handler: cast,
            priority: 50,
            scopes: ['item']
        }
    ]
};
